local ReliquaryMaker = {}
local PRODUCTS = {
    wooden_reliquary = { name = "Leseni relikviar", woodCost = 2, time = 2, cost = 30, sanctity = 4, description = "Preprost lesen relikviar za relikvije." },
    silver_reliquary = { name = "Srebrni relikviar", silverCost = 2, woodCost = 1, time = 4, cost = 120, sanctity = 8, prestige = 3, description = "Srebrni relikviar z graviranim okrasjem." },
    gold_reliquary = { name = "Zlati relikviar", goldCost = 1, silverCost = 1, woodCost = 1, time = 6, cost = 280, sanctity = 12, prestige = 7, happiness = 1, description = "Zlati relikviar za pomembne relikvije." },
    crystal_reliquary = { name = "Kristalni relikviar", glassCost = 2, goldCost = 1, silverCost = 1, time = 8, cost = 600, sanctity = 16, prestige = 14, happiness = 2, description = "Kristalni relikviar z razgledom na relikvijo." },
    jewel_reliquary = { name = "Draguljni relikviar", goldCost = 2, silverCost = 1, jewelCost = 2, glassCost = 1, time = 11, cost = 1300, sanctity = 22, prestige = 25, happiness = 5, description = "Relikviar z dragulji za katedralo." },
    royal_shrine_reliquary = { name = "Kraljevski svetiščni relikviar", goldCost = 4, silverCost = 2, jewelCost = 4, pearlCost = 2, glassCost = 2, time = 16, cost = 3200, sanctity = 40, prestige = 70, happiness = 14, description = "Veliki kraljevski svetiščni relikviar z dragulji in biseri." },
}
local BUILDINGS = {
    workshop = { name = "Relikviarska delavnica", cost = { gold = 300, wood = 130 }, upkeep = 8, qualityBonus = 5 },
    forge = { name = "Relikviarska kovačija", cost = { gold = 900, wood = 220, stone = 200, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    crystal_room = { name = "Kristalna soba", cost = { gold = 1900, wood = 300, stone = 400, glass = 8, silver = 25 }, upkeep = 45, qualityBonus = 30 },
    royal_reliquary_atelier = { name = "Kraljevski atelje relikviarjev", cost = { gold = 7500, wood = 600, stone = 800, gold = 80, jewel = 25 }, upkeep = 140, qualityBonus = 55, prestigeBonus = 35 },
}
ReliquaryMaker.woodStock = 14; ReliquaryMaker.silverStock = 8; ReliquaryMaker.goldStock = 8; ReliquaryMaker.glassStock = 8; ReliquaryMaker.jewelStock = 6; ReliquaryMaker.pearlStock = 4
ReliquaryMaker.productStock = {}; ReliquaryMaker.buildings = {}; ReliquaryMaker.maker = nil; ReliquaryMaker.activeMaking = {}; ReliquaryMaker.totalProducts = 0; ReliquaryMaker.dayTimer = 0
function ReliquaryMaker.init() ReliquaryMaker.woodStock=14; ReliquaryMaker.silverStock=8; ReliquaryMaker.goldStock=8; ReliquaryMaker.glassStock=8; ReliquaryMaker.jewelStock=6; ReliquaryMaker.pearlStock=4; ReliquaryMaker.productStock={}; ReliquaryMaker.buildings={}; ReliquaryMaker.maker=nil; ReliquaryMaker.activeMaking={}; ReliquaryMaker.totalProducts=0; ReliquaryMaker.dayTimer=0; print("[ReliquaryMaker] Royal Reliquary Maker System initialized (6 products, 4 buildings)") end
function ReliquaryMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ReliquaryMaker.maker={name=n or ("Relikviar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Relikviar najet: %s (spretnost: %d)",ReliquaryMaker.maker.name,s),"success") end; return true end
function ReliquaryMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ReliquaryMaker.build(id) local ok,e=ReliquaryMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ReliquaryMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ReliquaryMaker.getQualityBonus() local b=0; for _,bd in ipairs(ReliquaryMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ReliquaryMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ReliquaryMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and ReliquaryMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ReliquaryMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.glassCost and ReliquaryMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.jewelCost and ReliquaryMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ReliquaryMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ReliquaryMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ReliquaryMaker.maker then return false,"Potreben relikviar" end; return true end
function ReliquaryMaker.make(pt,qty) qty=qty or 1; local ok,e=ReliquaryMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ReliquaryMaker.woodStock=ReliquaryMaker.woodStock-d.woodCost*qty end; if d.silverCost then ReliquaryMaker.silverStock=ReliquaryMaker.silverStock-d.silverCost*qty end; if d.goldCost then ReliquaryMaker.goldStock=ReliquaryMaker.goldStock-d.goldCost*qty end; if d.glassCost then ReliquaryMaker.glassStock=ReliquaryMaker.glassStock-d.glassCost*qty end; if d.jewelCost then ReliquaryMaker.jewelStock=ReliquaryMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ReliquaryMaker.pearlStock=ReliquaryMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ReliquaryMaker.maker then t=math.max(1,t-math.floor(ReliquaryMaker.maker.skill/12)) end; table.insert(ReliquaryMaker.activeMaking,{id="reliquary_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,sanctity=d.sanctity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ReliquaryMaker.completeMaking(m) local q=1.0+(ReliquaryMaker.getQualityBonus()/100); if ReliquaryMaker.maker then q=q+(ReliquaryMaker.maker.skill/180) end; q=math.min(2.0,q); ReliquaryMaker.productStock[m.productType]=(ReliquaryMaker.productStock[m.productType] or 0)+m.quantity; ReliquaryMaker.totalProducts=ReliquaryMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ReliquaryMaker.maker then ReliquaryMaker.maker.itemsMade=ReliquaryMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then ReliquaryMaker.maker.skill=math.min(100,ReliquaryMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Relikviar izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"reliquary.completed",{productName=m.productName,sanctity=m.sanctity}) end end
function ReliquaryMaker.update(dt) if not _G.state then return end; ReliquaryMaker.dayTimer=ReliquaryMaker.dayTimer+dt; if ReliquaryMaker.dayTimer>=30 then ReliquaryMaker.dayTimer=0; for i=#ReliquaryMaker.activeMaking,1,-1 do local m=ReliquaryMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ReliquaryMaker.completeMaking(m); table.remove(ReliquaryMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ReliquaryMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ReliquaryMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ReliquaryMaker.getStats() return {woodStock=ReliquaryMaker.woodStock,silverStock=ReliquaryMaker.silverStock,goldStock=ReliquaryMaker.goldStock,glassStock=ReliquaryMaker.glassStock,jewelStock=ReliquaryMaker.jewelStock,pearlStock=ReliquaryMaker.pearlStock,productStock=ReliquaryMaker.productStock,numBuildings=#ReliquaryMaker.buildings,hasMaker=ReliquaryMaker.maker~=nil,makerName=ReliquaryMaker.maker and ReliquaryMaker.maker.name or "—",makerSkill=ReliquaryMaker.maker and ReliquaryMaker.maker.skill or 0,activeMaking=#ReliquaryMaker.activeMaking,totalProducts=ReliquaryMaker.totalProducts} end
return ReliquaryMaker
